// BFS on an implicit graph: word ladder where neighbours are generated by
// changing one letter, with path reconstruction.

#include <algorithm>
#include <iostream>
#include <queue>
#include <string>
#include <unordered_map>
#include <unordered_set>
#include <vector>

std::vector<std::string> ladder(const std::string &begin, const std::string &end, const std::unordered_set<std::string> &dict)
{
    std::unordered_map<std::string, std::string> parent;                // doubles as the visited set
    std::queue<std::string> q;
    parent[begin] = "";
    q.push(begin);
    while (!q.empty())
    {
        std::string cur = q.front(); q.pop();
        if (cur == end) break;
        for (std::size_t i = 0; i < cur.size(); ++i)                    // neighbours are generated, never stored
        {
            std::string next = cur;
            for (char c = 'a'; c <= 'z'; ++c)
            {
                next[i] = c;
                if (dict.count(next) && !parent.count(next)) { parent[next] = cur; q.push(next); }
            }
        }
    }
    std::vector<std::string> path;
    if (!parent.count(end)) return path;
    for (std::string w = end; !w.empty(); w = parent[w]) path.push_back(w);
    std::reverse(path.begin(), path.end());
    return path;
}

int main()
{
    std::unordered_set<std::string> dict{"hot", "dot", "dog", "lot", "log", "cog", "hog", "cot"};
    auto path = ladder("hit", "cog", dict);
    std::cout << "shortest ladder (" << path.size() << " words):";
    for (auto &w : path) std::cout << ' ' << w;
    std::cout << "\nladder to an unreachable word: " << ladder("hit", "xyz", dict).size() << " words\n";
    std::cout << "implicit graphs (puzzle states, word changes, chess moves): generate neighbours on the fly; BFS gives the fewest moves\n";
}
